function validate([customers, boardingCost, runningCost]) {
  if (!Array.isArray(customers) || customers.length < 1 || customers.length > 100000) return 'customers needs 1 to 100000 values.';
  if (customers.some(c => !Number.isInteger(c) || c < 0 || c > 50)) return 'Each customers[i] is a whole number from 0 to 50.';
  if (!Number.isInteger(boardingCost) || boardingCost < 1 || boardingCost > 100) return 'boardingCost is between 1 and 100.';
  if (!Number.isInteger(runningCost) || runningCost < 1 || runningCost > 100) return 'runningCost is between 1 and 100.';
  return null;
}

