function minOperationsMaxProfit(customers, boardingCost, runningCost) {
  let waiting = 0;
  let profit = 0;
  let bestProfit = 0;
  let bestRotations = -1;
  let rotations = 0;

  while (rotations < customers.length || waiting > 0) {
    if (rotations < customers.length) {
      waiting += customers[rotations];
    }
    const boarding = Math.min(4, waiting);
    waiting -= boarding;
    rotations++;
    profit += boarding * boardingCost - runningCost;
    if (profit > bestProfit) {
      bestProfit = profit;
      bestRotations = rotations;
    }
  }
  return bestRotations;
}

