function minOperationsMaxProfit(customers, boardingCost, runningCost) {
  const total = customers.reduce((a, b) => a + b, 0);
  const limit = customers.length + total;
  let answer = -1;
  let best = 0;
  for (let k = 1; k <= limit; k++) {
    // Re-run the first k turns from scratch with an explicit line of people.
    const line = [];
    let riders = 0;
    for (let turn = 0; turn < k; turn++) {
      for (let p = 0; turn < customers.length && p < customers[turn]; p++) line.push(turn);
      for (let seat = 0; seat < 4 && line.length > 0; seat++) { line.shift(); riders++; }
    }
    const value = riders * boardingCost - k * runningCost;
    if (value > best) { best = value; answer = k; }
  }
  return answer;
}

