function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const n = 2000;
    const cap = int(0, 3) === 0 ? 8 : 50;
    const customers = Array.from({ length: n }, () => int(0, cap));
    return [customers, int(1, 100), int(1, 100)];
  }
  const n = int(1, 6);
  const cap = [0, 3, 6, 12, 50][int(0, 4)];
  const customers = Array.from({ length: n }, () => (rand() < 0.25 ? 0 : int(0, cap)));
  const boardingCost = int(1, 12);
  const runningCost = int(1, 4 * boardingCost + 6);
  return [customers, boardingCost, runningCost];
}
